import yaml, re, os
r = yaml.safe_load(open('governance/check-registry.yaml'))['checks']
print('keys:', sorted(set(k for c in r for k in c)))
def path(c):
    for k in ('script','command','cmd','run','path','entry'):
        if k in c: return str(c[k])
    return ''
kept = {'migration_reproducibility_deep','provenance_artefact_audit','author_fidelity','test_db_integrity','judgment_handoff_shape','research_dod_session','schema_reference_audit','claude_md_spine','attestation_presence','attestation_schema','supersession_backpointer_audit','research_tooling_separation','research_contract_sync','migration_reproducibility'}
tabs = ['source_slug_links','data_capture_status','citation_mining','search_admissions','found_under_slug','evidence_sources.tier','tier','items','populations','population_code','specification_extraction_links','convergence_assessment','search_execution_artefacts','file_anchor','MODEL_TABLE_MAP','axes']
print('\n== kept gates: script, lines, deleted-object references')
for c in r:
    if c['id'] in kept:
        p = path(c); m = re.search(r'(scripts/\S+\.py|\.claude/\S+\.py|scripts/\S+\.sh)', p); f = m.group(1) if m else p
        refs = {}
        if f and os.path.exists(f):
            s = open(f).read(); n = s.count('\n')
            for t in tabs:
                k = len(re.findall(r'\b'+re.escape(t)+r'\b', s))
                if k: refs[t] = k
        else: n = '?'
        print(f"  {c['id']:34s} {str(c.get('level')):9s} {f:55s} {n} {refs}")
print('\n== all 85: id | level | script | purpose (trimmed)')
for c in sorted(r, key=lambda c: (c['id'] in kept, c['id'])):
    d = c.get('reason') or c.get('description') or c.get('purpose') or c.get('what') or ''
    d = ' '.join(str(d).split())[:150]
    p = path(c); m = re.search(r'(scripts/\S+\.py|\.claude/\S+\.py|scripts/\S+\.sh|tools/\S+\.py)', p); f = m.group(1) if m else p[:40]
    print(f"{'KEEP' if c['id'] in kept else 'DEL ':4s} {c['id']:36s} {str(c.get('level')):9s} {f:48s} {d}")
PY

